// ***************
// Filename: spi_flash_ctrl_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of spi_flash_ctrl: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to spi_flash_ctrl's logic on named ports,
//   its status comes back on input ports. SPI NOR flash controller: generic
//   command, address, length, clock divider, status, interrupt enable.
//   Generated by ip/scripts/regmap_gen.py from spi_flash_ctrl_regs.json: edit
//   the JSON and regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "SPFL" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CMD         RW   write starts a command (ignored and CMD_ERR while
//                       busy); reads back the last one, reset 0x0
//                       [7:0] OPCODE: flash opcode
//                       [8] ADDR_EN: send the 3 address bytes
//                       [15:12] DUMMY: dummy bytes after the address
//                       [16] READ_DATA: LEN data bytes read to m_axis
//                       [17] WRITE_DATA: LEN data bytes written from s_axis
//     0x14 ADDR        RW   flash address (3 bytes), reset 0x0
//     0x18 LEN         RW   data bytes (0..65535), reset 0x0
//     0x1C CLKDIV      RW   sclk half period in clocks (minimum 3), reset 0x4
//     0x20 STATUS      CMD  status; write 1 to [2:1] to clear those flags
//                       [0] BUSY: command in progress
//                       [1] DONE: command finished (sticky, W1C)
//                       [2] CMD_ERR: CMD written while busy (sticky, W1C)
//     0x24 IRQ_EN      RW   [0] irq_o = DONE, reset 0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-20
module spi_flash_ctrl_regs (
  input  logic          aclk,           // clock
  input  logic          aresetn,        // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: spi_flash_ctrl_regs_if.regs (src/include/spi_flash_ctrl_regs_if.sv) {cmd_o=cfg_cmd cmd_wr_o=cfg_cmd_wr addr_o=cfg_addr addr_wr_o=cfg_addr_wr len_o=cfg_len len_wr_o=cfg_len_wr clkdiv_o=cfg_clkdiv clkdiv_wr_o=cfg_clkdiv_wr status_i=sts_status status_o=cfg_status status_wr_o=cfg_status_wr irq_en_o=cfg_irq_en irq_en_wr_o=cfg_irq_en_wr}
  spi_flash_ctrl_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [32-1:0] cmd_o;
  logic cmd_wr_o;
  logic [24-1:0] addr_o;
  logic addr_wr_o;
  logic [16-1:0] len_o;
  logic len_wr_o;
  logic [16-1:0] clkdiv_o;
  logic clkdiv_wr_o;
  logic [3-1:0] status_i;
  logic [3-1:0] status_o;
  logic status_wr_o;
  logic irq_en_o;
  logic irq_en_wr_o;
  assign r.cfg_cmd = cmd_o;
  assign r.cfg_cmd_wr = cmd_wr_o;
  assign r.cfg_addr = addr_o;
  assign r.cfg_addr_wr = addr_wr_o;
  assign r.cfg_len = len_o;
  assign r.cfg_len_wr = len_wr_o;
  assign r.cfg_clkdiv = clkdiv_o;
  assign r.cfg_clkdiv_wr = clkdiv_wr_o;
  assign status_i = r.sts_status;
  assign r.cfg_status = status_o;
  assign r.cfg_status_wr = status_wr_o;
  assign r.cfg_irq_en = irq_en_o;
  assign r.cfg_irq_en_wr = irq_en_wr_o;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "SPFL";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CMD = 8'h10;
  localparam logic [7:0] A_ADDR = 8'h14;
  localparam logic [7:0] A_LEN = 8'h18;
  localparam logic [7:0] A_CLKDIV = 8'h1C;
  localparam logic [7:0] A_STATUS = 8'h20;
  localparam logic [7:0] A_IRQ_EN = 8'h24;
  localparam int MAP_WORDS = 10;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  wire unused_addr_lsbs = &{1'b0, wr_addr[1:0], rd_addr[1:0]};   // word access: the byte offset is not decoded
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] cmd_q;
  logic [31:0] addr_q;
  logic [31:0] len_q;
  logic [31:0] clkdiv_q;
  logic [31:0] status_q;
  logic [31:0] irq_en_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      cmd_q <= 32'h0;
      cmd_wr_o <= 1'b0;
      addr_q <= 32'h0;
      addr_wr_o <= 1'b0;
      len_q <= 32'h0;
      len_wr_o <= 1'b0;
      clkdiv_q <= 32'h4;
      clkdiv_wr_o <= 1'b0;
      status_q <= '0;
      status_wr_o <= 1'b0;
      irq_en_q <= 32'h0;
      irq_en_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE);   // writes to read-only words: SLVERR
      begin
        cmd_wr_o <= wr_en && wa == A_CMD;
        if (wr_en && wa == A_CMD) cmd_q <= (cmd_q & ~wmask) | (wr_data & wmask);
      end
      begin
        addr_wr_o <= wr_en && wa == A_ADDR;
        if (wr_en && wa == A_ADDR) addr_q <= (addr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        len_wr_o <= wr_en && wa == A_LEN;
        if (wr_en && wa == A_LEN) len_q <= (len_q & ~wmask) | (wr_data & wmask);
      end
      begin
        clkdiv_wr_o <= wr_en && wa == A_CLKDIV;
        if (wr_en && wa == A_CLKDIV) clkdiv_q <= (clkdiv_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        if (wr_en && wa == A_STATUS) status_q <= (status_q & ~wmask) | (wr_data & wmask);
      end
      begin
        irq_en_wr_o <= wr_en && wa == A_IRQ_EN;
        if (wr_en && wa == A_IRQ_EN) irq_en_q <= (irq_en_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign cmd_o = cmd_q[32-1:0];
  assign addr_o = addr_q[24-1:0];
  assign len_o = len_q[16-1:0];
  assign clkdiv_o = clkdiv_q[16-1:0];
  assign status_o = status_q[3-1:0];
  assign irq_en_o = irq_en_q[1-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CMD: rd_data = 32'(cmd_q[32-1:0]);
      A_ADDR: rd_data = 32'(addr_q[24-1:0]);
      A_LEN: rd_data = 32'(len_q[16-1:0]);
      A_CLKDIV: rd_data = 32'(clkdiv_q[16-1:0]);
      A_STATUS: rd_data = 32'(status_i);
      A_IRQ_EN: rd_data = 32'(irq_en_q[1-1:0]);
      default: begin
      end
    endcase
  end
endmodule
